frappe.listview_settings['Contract'] = {
    add_fields: ["custom_contract_status"],
    
    // This function completely hijacks the standard Status column in the List View
    get_indicator: function(doc) {
        let s = doc.custom_contract_status || "Draft";
        
        // 1. Red Statuses (Closed, Terminated, Rejected)
        if (['Terminated', 'Closed', 'Final Rejected', 'Legal Rejected', 'Finance Rejected', 'HR Rejected', 'Team Lead Rejected', 'CEO Rejected'].includes(s)) {
            return [__(s), "red", "custom_contract_status,=," + s];
        } 
        // 2. Purple Statuses (Amendments)
        else if (s.includes('Amendment') || s === 'Amended') {
            return [__(s), "purple", "custom_contract_status,=," + s];
        } 
        // 3. Blue Statuses (Renewals)
        else if (s.includes('Renewal') || s === 'Renewed') {
            return [__(s), "blue", "custom_contract_status,=," + s];
        } 
        // 4. Green Statuses (Approved, Issued)
        else if (['Issued', 'Internally Approved', 'CEO Approved', 'Team Lead Approved'].includes(s)) {
            return [__(s), "green", "custom_contract_status,=," + s];
        } 
        // 5. Orange Statuses (Draft, Pending stages)
        else {
            return [__(s), "orange", "custom_contract_status,=," + s];
        }
    }
};

frappe.ui.form.on('Appraisal', {
