        render_progress_bar(frm);
        apply_manager_security_lock(frm);
        setup_competencies(frm);
        
        // --- ADDED LAYOUT SHIELD TO STOP LEAKS INTO OVERVIEW TAB ---
        lock_and_clean_overview_tab(frm);

        // --- FORCES THE TOP BADGE TO MATCH WORKFLOW STATE ---
