        if (!$('#hide-grid-placeholders-css').length) {
            $('head').append(`
                <style id="hide-grid-placeholders-css">
                    .grid-row input::placeholder, 
                    .grid-row textarea::placeholder,
                    .control-input textarea::placeholder {
                        color: transparent !important;
                    }
                    .grid-static-col:empty::before {
                        content: "" !important;
                    }
                    .stepper-container {
                        margin-bottom: 25px !important;
                        padding: 10px 0;
                        background: transparent;
                    }
