                if (row.doc.objective === 'Objective') row.doc.objective = '';
                if (row.doc.how_will_you_achieve === 'How will you achieve') row.doc.how_will_you_achieve = '';
                if (row.doc.midterm_achievements === 'Mid-term achievements') row.doc.midterm_achievements = '';
                if (row.doc.annual_achievements === 'Annual achievements') row.doc.annual_achievements = '';
            });
            grid.refresh();
        }

        setTimeout(() => {
            $('.grid-row input, textarea').each(function() {
                let val = $(this).val() || '';
                if (['Objective', 'How will you achieve', 'Mid-term achievements', 'Annual achievements'].includes(val.trim())) {
                    $(this).val('').trigger('change');
                }
                if (val.includes('Feedback to your manager about how you feel')) {
                    $(this).val('').trigger('change');
                }
            });
        }, 200);

        if (frm.doc.appraisal_cycle) {
            toggle_mid_term_vs_annual(frm);
            check_cycle_dates_and_lock(frm);
            enforce_field_visibility(frm);
            sync_status_columns(frm); 
        }

        if (frm.doc.appraisal_cycle && frm.doc.appraisal_cycle.toLowerCase().includes('annual') && frm.doc.employee) {
            fetch_and_render_mid_term(frm);
        }

        if (!frm.self_appraisal_tab_bound) {
            frm.self_appraisal_tab_bound = true;
            $(document).on('click', 'a.nav-link:contains("Self Appraisal")', function() {
                setTimeout(() => {
                    let current_cycle = get_cycle_type(frm);
                    if (current_cycle.is_annual) {
                        enforce_field_visibility(frm);
                    }
                }, 100);
            });
        }

        let checks = 0;
        let ui_watchdog = setInterval(() => {
            render_progress_bar(frm); 
            
            let btn = $('button:contains("View Goals")');
            if (btn.is(':visible')) {
                frm.remove_custom_button('View Goals');
                btn.hide(); 
            }

            let is_employee = (frappe.session.user === frm.doc.custom_employee_email || frappe.session.user === frm.doc.employee_email);
            let state = frm.doc.workflow_state || 'Pending';
            let current_cycle = get_cycle_type(frm);

            if (current_cycle.is_mid_term) {
                let nuke_fields = [
                    'custom_technical__behavio', 
                    'custom_annual_manager_feedback', 
                    'custom_manager_review__feedback',
                    'custom_annual_employee_performance_development_needs',
                    'custom_midterm_employee_reflections',
                    'custom_midterm_employee_performance_development_needs',
                    'custom_midterm_employee_upward_feedback'
                ];
                nuke_fields.forEach(f => {
                    if (frm.fields_dict[f]) set_property(frm, f, 'hidden', 1);
                });

                let is_objective_phase = (state === 'Pending' || state === 'Draft' || state === 'Objective Review Pending');
                let has_feedback = frm.doc.custom_midterm_manager_feedback ? true : false;
                let show_midterm_mgr_section = is_employee ? has_feedback : !is_objective_phase;

                if (frm.fields_dict.custom_midterm_manager_feedback) {
                    set_property(frm, 'custom_midterm_manager_feedback', 'hidden', show_midterm_mgr_section ? 0 : 1);
                }

                if (frm.fields_dict.custom_technical__behavio) {
                    set_property(frm, 'custom_technical__behavio', 'hidden', 1);
                    let tech_tab = $('a.nav-link[data-fieldname="custom_technical__behavio"]').parent();
                    if (tech_tab.css('display') !== 'none') tech_tab.hide();
                }

                const manager_tab = $('a.nav-link:contains("Manager Feedback")').parent();
                if (show_midterm_mgr_section) {
                    if (manager_tab.css('display') === 'none') manager_tab.show();
                } else {
                    if (manager_tab.css('display') !== 'none') {
                        manager_tab.hide();
                        if ($('a.nav-link:contains("Manager Feedback")').hasClass('active')) {
                            $('a.nav-link:contains("Self Appraisal")')[0].click();
                        }
                    }
                }
            } else if (current_cycle.is_annual) {
                let has_mgr_feedback = frm.doc.custom_annual_manager_feedback ? true : false;
                let has_mgr_rating = frm.doc.custom_annual_manager_rating ? true : false;
                let show_manager_section = false;

                if (is_employee) {
                    show_manager_section = (state === 'Completed' || has_mgr_feedback || has_mgr_rating);
                } else {
                    show_manager_section = (state === 'Pending Manager Review' || state === 'Completed');
                }

                const manager_tab = $('a.nav-link:contains("Manager Feedback")').parent();
                if (show_manager_section) {
                    if (manager_tab.css('display') === 'none') manager_tab.show();
                } else {
                    if (manager_tab.css('display') !== 'none') {
                        manager_tab.hide();
                        if ($('a.nav-link:contains("Manager Feedback")').hasClass('active')) {
                            $('a.nav-link:contains("Self Appraisal")')[0].click();
                        }
                    }
                }

                if (frm.fields_dict.custom_rating_instructions) {
                    let instr_wrapper = $(frm.fields_dict.custom_rating_instructions.wrapper);
                    if (is_employee) {
                        if (instr_wrapper.css('display') !== 'none') instr_wrapper.hide();
                    } else {
                        if (show_manager_section) {
                            if (instr_wrapper.css('display') === 'none') instr_wrapper.show();
                        } else {
                            if (instr_wrapper.css('display') !== 'none') instr_wrapper.hide();
                        }
                    }
                }
            }

            enforce_field_visibility(frm);

            checks++;
            if (checks > 10) clearInterval(ui_watchdog);
        }, 200); 
    },

    appraisal_cycle: function(frm) {
        setTimeout(() => {
            render_progress_bar(frm);
            if (frm.doc.appraisal_cycle) {
                toggle_mid_term_vs_annual(frm);
                check_cycle_dates_and_lock(frm);
                enforce_field_visibility(frm);
                sync_status_columns(frm);
                let cycle = get_cycle_type(frm);
                if (cycle.is_annual && frm.doc.employee) {
                    fetch_and_render_mid_term(frm);
                }
            }
            apply_manager_security_lock(frm);
            setup_competencies(frm);
        }, 300);
    },

    employee: function(frm) {
        setTimeout(() => {
            render_progress_bar(frm);
            let cycle = get_cycle_type(frm);
            if (cycle.is_annual && frm.doc.employee) {
                fetch_and_render_mid_term(frm);
            }
            apply_manager_security_lock(frm);
            setup_competencies(frm);
            if (frm.doc.appraisal_cycle) {
                enforce_field_visibility(frm);
                sync_status_columns(frm);
            }
        }, 300);
    },

    validate: function(frm) {
        if (frm.doc.self_ratings && frm.doc.self_ratings.length > 0) {
            let total = frm.doc.self_ratings.length;
            let base_weight = Math.floor(100 / total);
            let remainder = 100 - (base_weight * total);
            $.each(frm.doc.self_ratings, function(i, row) { row.weightage = (i === 0) ? (base_weight + remainder) : base_weight; });
        }
        if (frm.doc.goals && frm.doc.goals.length > 0) {
            let total = frm.doc.goals.length;
            let base_weight = Math.floor(100 / total);
            let remainder = 100 - (base_weight * total);
            $.each(frm.doc.goals, function(i, row) { row.per_weightage = (i === 0) ? (base_weight + remainder) : base_weight; });
        }
    },

    before_workflow_action: function(frm) {
        if (frm.selected_workflow_action && frm.selected_workflow_action.includes('Finalize')) {
            let cycle = get_cycle_type(frm);
            let missing_competency = false;
            let tables = ['custom_behavioural_competencies', 'custom_executive_technical_competencies', 'custom_leadership_technical_competencies'];
            
            tables.forEach(table => {
                if (frm.fields_dict[table] && !frm.get_docfield(table).hidden && frm.doc[table]) {
                    frm.doc[table].forEach(row => {
                        if (cycle.is_mid_term && !row.rating) {
                            missing_competency = true;
                        } else if (cycle.is_annual && !row.annual_rating) {
                            missing_competency = true;
                        }
                    });
                }
            });

            if (missing_competency) {
                frappe.throw(__('Please fill out all ratings in the <b>Technical & Behavioural Competencies</b> tab before finalizing.'));
            }

            if (cycle.is_annual) {
                if (!frm.doc.custom_annual_manager_feedback && !frm.doc.custom_manager_review__feedback) {
                    frappe.throw(__('Please provide the <b>Annual Manager Feedback</b> before finalizing.'));
                }
                if (!frm.doc.custom_annual_manager_rating) {
                    frappe.throw(__('Please select the <b>Annual Manager Rating</b> before finalizing.'));
                }
            }
        }
    }
});

