// --- HELPER FUNCTIONS ---

function sync_status_columns(frm) {
    if (frm.is_new()) return; 
    let cycle = get_cycle_type(frm);
    let state = frm.doc.workflow_state || 'Draft';

    if (cycle.is_mid_term) {
        let expected_obj = 'Pending';
        let expected_mid = 'Pending';
        let expected_ann = 'N/A';

        if (state === 'Draft' || state === 'Pending') {
            expected_obj = 'Pending'; expected_mid = 'Pending';
        } else if (state === 'Objective Review Pending') {
            expected_obj = 'Under Review'; expected_mid = 'Pending';
        } else if (state === 'Objectives Approved') {
            expected_obj = 'Approved'; expected_mid = 'Pending';
        } else if (state === 'Pending Manager Review') {
            expected_obj = 'Approved'; expected_mid = 'Manager Review';
        } else if (state === 'Completed') {
            expected_obj = 'Approved'; expected_mid = 'Completed';
        }

        let updates = {};
        if (frm.fields_dict.custom_objective_status && frm.doc.custom_objective_status !== expected_obj) updates['custom_objective_status'] = expected_obj;
        if (frm.fields_dict.custom_midterm_status && frm.doc.custom_midterm_status !== expected_mid) updates['custom_midterm_status'] = expected_mid;
        if (frm.fields_dict.custom_annual_status && frm.doc.custom_annual_status !== expected_ann) updates['custom_annual_status'] = expected_ann;

        if (Object.keys(updates).length > 0) {
            frappe.db.set_value('Appraisal', frm.doc.name, updates).then(() => {
                Object.assign(frm.doc, updates);
                frm.refresh_fields();
            });
        }
    } else if (cycle.is_annual && frm.doc.employee) {
        frappe.call({
            method: 'frappe.client.get_list',
            args: {
                doctype: 'Appraisal',
                filters: {
                    employee: frm.doc.employee,
                    docstatus: ['<', 2],
                    name: ['!=', frm.doc.name]
                },
                fields: ['name', 'appraisal_cycle', 'custom_objective_status', 'custom_midterm_status'],
                order_by: 'creation desc'
            },
            callback: function(r) {
                if (r.message && r.message.length > 0) {
                    let mid_term = r.message.find(d => d.appraisal_cycle && (d.appraisal_cycle.toLowerCase().includes('mid') || d.appraisal_cycle.toLowerCase().includes('half')));
                    if (!mid_term) mid_term = r.message[0];

                    let live_obj = (mid_term && mid_term.custom_objective_status) ? mid_term.custom_objective_status : 'Pending';
                    let live_mid = (mid_term && mid_term.custom_midterm_status) ? mid_term.custom_midterm_status : 'Pending';
                    let live_ann = (live_mid === 'Completed') ? (frm.doc.custom_annual_status === 'N/A' || !frm.doc.custom_annual_status ? 'Pending' : frm.doc.custom_annual_status) : 'N/A';

                    let updates = {};
                    if (frm.fields_dict.custom_objective_status && frm.doc.custom_objective_status !== live_obj) updates['custom_objective_status'] = live_obj;
                    if (frm.fields_dict.custom_midterm_status && frm.doc.custom_midterm_status !== live_mid) updates['custom_midterm_status'] = live_mid;
                    if (frm.fields_dict.custom_annual_status && frm.doc.custom_annual_status !== live_ann) updates['custom_annual_status'] = live_ann;

                    if (Object.keys(updates).length > 0) {
                        frappe.db.set_value('Appraisal', frm.doc.name, updates).then(() => {
                            Object.assign(frm.doc, updates);
                            frm.refresh_fields();
                        });
                    }
                }
            }
        });
    }
}

function lock_and_clean_overview_tab(frm) {
    if (!frm.is_new()) {
        let overview_fields = [
            'employee', 'employee_name', 'company', 'appraisal_cycle', 
            'start_date', 'end_date', 'manager', 'department', 'designation'
        ];
        overview_fields.forEach(f => { 
            if (frm.fields_dict[f]) set_property(frm, f, 'read_only', 1); 
        });
    }

    setTimeout(() => {
        let leaked_selectors = [
            '[data-fieldname="custom_midterm_manager_feedback"]',
            '[data-fieldname="custom_annual_manager_feedback"]',
            '[data-fieldname="custom_annual_manager_rating"]',
            '[data-fieldname="custom_technical__behavio"]',
            '[data-fieldname="custom_behavioural_competencies"]'
        ];
        
        leaked_selectors.forEach(selector => {
            let $el = $(selector);
            if ($el.closest('#overview').length > 0) {
                $el.hide();
            }
        });
    }, 400);
}

function set_property(frm, fieldname, prop, value) {
    let field = frm.fields_dict[fieldname];
    if (field && field.df[prop] !== value) {
        frm.set_df_property(fieldname, prop, value);
    }
}

function get_cycle_type(frm) {
    let cycle_name = frm.doc.appraisal_cycle ? frm.doc.appraisal_cycle.toLowerCase() : '';
    let is_mid_term = cycle_name.includes('mid') || cycle_name.includes('half');
    let is_annual = cycle_name !== '' && !is_mid_term;
    return { is_mid_term, is_annual };
}

function safe_grid_update(grid, fieldname, prop, val) {
    if (grid && grid.get_docfield && grid.get_docfield(fieldname)) {
        try {
            grid.update_docfield_property(fieldname, prop, val);
        } catch (e) {
            console.warn(`Failed to update grid field: ${fieldname}`);
        }
    }
}

function move_field(frm, field_to_move, target_field, position) {
    let source_field = frm.fields_dict[field_to_move];
    let tgt_field = frm.fields_dict[target_field];

    if (source_field && tgt_field && source_field.wrapper && tgt_field.wrapper) {
        let $source = $(source_field.wrapper);
        let $target = $(tgt_field.wrapper);

        if (position === 'before' && $target.prev()[0] === $source[0]) return;
        if (position === 'after' && $target.next()[0] === $source[0]) return;

        if (position === 'before') {
            $source.insertBefore($target);
        } else {
            $source.insertAfter($target);
        }
    }
}

function enforce_field_visibility(frm) {
    if (!frm.doc.appraisal_cycle) return;
    
    let cycle = get_cycle_type(frm);
    let is_employee = (frappe.session.user === frm.doc.custom_employee_email || frappe.session.user === frm.doc.employee_email);
    let state = frm.doc.workflow_state || 'Pending';
    
    if (frm.fields_dict.custom_linked_midterm_appraisal) {
        set_property(frm, 'custom_linked_midterm_appraisal', 'hidden', 1);
    }

    if (cycle.is_mid_term) {
        if (frm.fields_dict.custom_self_assessment_on_annual_progress) {
            set_property(frm, 'custom_self_assessment_on_annual_progress', 'hidden', 1);
        }
        if (frm.fields_dict.custom_annual_employee_performance_development_needs) {
            set_property(frm, 'custom_annual_employee_performance_development_needs', 'hidden', 1);
        }
        
        let is_objective_phase = (state === 'Pending' || state === 'Draft' || state === 'Objective Review Pending');
        let has_feedback = frm.doc.custom_midterm_manager_feedback ? true : false;
        let show_midterm_mgr_section = is_employee ? has_feedback : !is_objective_phase;

        if (frm.fields_dict.custom_midterm_manager_feedback) {
            set_property(frm, 'custom_midterm_manager_feedback', 'hidden', show_midterm_mgr_section ? 0 : 1);
            set_property(frm, 'custom_midterm_manager_feedback', 'label', '<b>Mid-Term Manager Feedback</b>');
            let can_mgr_edit = (!is_employee && state === 'Pending Manager Review');
            set_property(frm, 'custom_midterm_manager_feedback', 'read_only', can_mgr_edit ? 0 : 1);
        }

        if (frm.fields_dict.custom_upward_feedback_to_manager) {
            set_property(frm, 'custom_upward_feedback_to_manager', 'hidden', 1);
        }

        if (frm.fields_dict.custom_midterm_employee_upward_feedback) {
            set_property(frm, 'custom_midterm_employee_upward_feedback', 'hidden', is_objective_phase ? 1 : 0);
            set_property(frm, 'custom_midterm_employee_upward_feedback', 'label', 'Employee Upward Feedback');
            set_property(frm, 'custom_midterm_employee_upward_feedback', 'read_only', is_employee ? 0 : 1);
            move_field(frm, 'custom_midterm_employee_upward_feedback', 'custom_objectives__achievements', 'after');
        }

        if (frm.fields_dict.custom_manager_review__feedback) {
            set_property(frm, 'custom_manager_review__feedback', 'hidden', 1);
        }

        let nuke_fields = [
            'custom_technical__behavio', 
            'custom_annual_manager_feedback', 
            'custom_annual_manager_rating'
        ];
        nuke_fields.forEach(f => {
            if (frm.fields_dict[f]) set_property(frm, f, 'hidden', 1);
        });
        
        if (frm.fields_dict.custom_technical__behavio) {
            set_property(frm, 'custom_technical__behavio', 'hidden', 1);
            let tech_tab = $('a.nav-link[data-fieldname="custom_technical__behavio"]').parent();
            if(tech_tab.css('display') !== 'none') tech_tab.hide();
        }

        const manager_tab = $('a.nav-link:contains("Manager Feedback")').parent();
        if (show_midterm_mgr_section) {
            if(manager_tab.css('display') === 'none') manager_tab.show();
        } else {
            if(manager_tab.css('display') !== 'none') {
                manager_tab.hide();
                if ($('a.nav-link:contains("Manager Feedback")').hasClass('active')) {
                    $('a.nav-link:contains("Self Appraisal")')[0].click();
                }
            }
        }

    } else if (cycle.is_annual) {

        let has_mgr_feedback = frm.doc.custom_annual_manager_feedback ? true : false;
        let has_mgr_rating = frm.doc.custom_annual_manager_rating ? true : false;
        let show_manager_section = false;

        if (is_employee) {
            show_manager_section = (state === 'Completed' || has_mgr_feedback || has_mgr_rating);
        } else {
            show_manager_section = (state === 'Pending Manager Review' || state === 'Completed');
        }

        if (frm.fields_dict.custom_midterm_employee_upward_feedback) {
            set_property(frm, 'custom_midterm_employee_upward_feedback', 'hidden', 0);
            set_property(frm, 'custom_midterm_employee_upward_feedback', 'read_only', 1);
            set_property(frm, 'custom_midterm_employee_upward_feedback', 'label', '<b>Mid-Term Employee Summary</b><br><span style="font-weight: normal; font-size: 12px; color: #687684;">Key achievements till mid-term.</span>');
        }

        if (frm.fields_dict.custom_midterm_manager_feedback) {
            set_property(frm, 'custom_midterm_manager_feedback', 'hidden', 0);
            set_property(frm, 'custom_midterm_manager_feedback', 'read_only', 1);
            set_property(frm, 'custom_midterm_manager_feedback', 'label', '<b>Mid-Term Manager Feedback</b><br><span style="font-weight:normal;font-size:12px;color:#687684;">Please highlight any specific areas and feedback in line with the above self-appraisal. Please also include any agreed amendments to the current objectives if applicable which will become part of the annual review process.</span>');
        }

        if (frm.fields_dict.custom_self_assessment_on_annual_progress) {
            set_property(frm, 'custom_self_assessment_on_annual_progress', 'hidden', 0);
            set_property(frm, 'custom_self_assessment_on_annual_progress', 'read_only', is_employee ? 0 : 1);
        }

        if (frm.fields_dict.custom_upward_feedback_to_manager) {
            set_property(frm, 'custom_upward_feedback_to_manager', 'hidden', 0);
            set_property(frm, 'custom_upward_feedback_to_manager', 'read_only', is_employee ? 0 : 1);
            set_property(frm, 'custom_upward_feedback_to_manager', 'label', 'Upward Feedback to Manager');
        }

        if (frm.fields_dict.custom_annual_employee_performance_development_needs) {
            set_property(frm, 'custom_annual_employee_performance_development_needs', 'hidden', 0);
            set_property(frm, 'custom_annual_employee_performance_development_needs', 'read_only', 0); 
            set_property(frm, 'custom_annual_employee_performance_development_needs', 'label', '<b>Performance Development Needs : (to be agreed with Manager) (Refer to the competencies)</b><br><span style="font-weight: normal; font-size: 12px; color: #687684;">What are the performance development / learning needs for achieving the above objectives? (Please identify resources / budget requirement for this development plan and indicate when it must happen by)</span>');
        }

        if (frm.fields_dict.reflections) {
            set_property(frm, 'reflections', 'hidden', 0);
            set_property(frm, 'reflections', 'read_only', 0); 
        }

        if (frm.fields_dict.custom_annual_manager_feedback) {
            set_property(frm, 'custom_annual_manager_feedback', 'hidden', show_manager_section ? 0 : 1);
        }
        if (frm.fields_dict.custom_annual_manager_rating) {
            set_property(frm, 'custom_annual_manager_rating', 'hidden', show_manager_section ? 0 : 1);
        }
        if (frm.fields_dict.custom_manager_review__feedback) {
            set_property(frm, 'custom_manager_review__feedback', 'hidden', 1);
        }

        if (frm.fields_dict.custom_technical__behavio) {
            set_property(frm, 'custom_technical__behavio', 'hidden', show_manager_section ? 0 : 1);
            const technical_tab = $('a.nav-link[data-fieldname="custom_technical__behavio"]').parent();
            if (show_manager_section) {
                if(technical_tab.css('display') === 'none') technical_tab.show();
            } else {
                if(technical_tab.css('display') !== 'none') technical_tab.hide();
            }
        }

        const manager_tab = $('a.nav-link:contains("Manager Feedback")').parent();
        if (show_manager_section) {
            if(manager_tab.css('display') === 'none') manager_tab.show();
        } else {
            if(manager_tab.css('display') !== 'none') {
                manager_tab.hide();
                if ($('a.nav-link:contains("Manager Feedback")').hasClass('active')) {
                    $('a.nav-link:contains("Self Appraisal")')[0].click();
                }
            }
        }

        move_field(frm, 'custom_midterm_employee_upward_feedback', 'custom_self_assessment_on_annual_progress', 'before');
        move_field(frm, 'custom_midterm_manager_feedback', 'custom_self_assessment_on_annual_progress', 'before');
        move_field(frm, 'custom_upward_feedback_to_manager', 'custom_self_assessment_on_annual_progress', 'after');
        move_field(frm, 'custom_annual_employee_performance_development_needs', 'custom_upward_feedback_to_manager', 'after');
    }

    let cycle_name = frm.doc.appraisal_cycle || '';
    if (frm.last_enforced_cycle !== cycle_name) {
        frm.last_enforced_cycle = cycle_name;
        
        setTimeout(() => {
            let fields_to_resize = [
                'custom_self_assessment_on_annual_progress',
                'custom_upward_feedback_to_manager',
                'custom_midterm_employee_upward_feedback',
                'custom_annual_manager_feedback',
                'custom_annual_employee_performance_development_needs'
            ];
            
            fields_to_resize.forEach(field => {
                if (frm.fields_dict[field] && frm.fields_dict[field].$input) {
                    frm.fields_dict[field].$input.css({'min-height': '60px', 'height': '60px'});
                }
            });

            let fields_to_unhide = [
                'custom_midterm_employee_upward_feedback',
                'custom_midterm_manager_feedback'
            ];
            fields_to_unhide.forEach(fieldname => {
                if (frm.fields_dict[fieldname] && cycle.is_annual) {
                    const wrapper = $(frm.fields_dict[fieldname].wrapper);
                    if (wrapper.hasClass('hide') || wrapper.css('display') === 'none') {
                        wrapper.show().removeClass('hide').css('display', '');
                    }
                }
            });
        }, 300);
    }
}

function lock_overview_tab(frm) {
    if (!frm.is_new() && !frappe.user.has_role('HR Manager') && !frappe.user.has_role('System Manager')) {
        let overview_fields = ['employee', 'employee_name', 'company', 'appraisal_cycle', 'start_date', 'end_date', 'manager', 'department', 'designation'];
