function apply_manager_security_lock(frm) {
    let cycle = get_cycle_type(frm);
    let is_employee = (frappe.session.user === frm.doc.custom_employee_email || frappe.session.user === frm.doc.employee_email);
    let state = frm.doc.workflow_state || 'Pending';

    if (is_employee) {
        if (frm.fields_dict.custom_annual_employee_performance_development_needs) {
            set_property(frm, 'custom_annual_employee_performance_development_needs', 'read_only', 0); 
        }
        if (frm.fields_dict.custom_midterm_manager_feedback) {
            set_property(frm, 'custom_midterm_manager_feedback', 'read_only', 1);
        }
        if (frm.fields_dict.custom_midterm_employee_upward_feedback) {
            set_property(frm, 'custom_midterm_employee_upward_feedback', 'read_only', cycle.is_annual ? 1 : 0); 
        }
        if (frm.fields_dict.custom_self_assessment_on_annual_progress) {
            set_property(frm, 'custom_self_assessment_on_annual_progress', 'read_only', 0);
        }
        if (frm.fields_dict.custom_upward_feedback_to_manager) {
            set_property(frm, 'custom_upward_feedback_to_manager', 'read_only', 0);
        }
        if (frm.fields_dict.reflections) {
            set_property(frm, 'reflections', 'read_only', 0);
        }
        if (frm.fields_dict.custom_annual_manager_rating) {
            set_property(frm, 'custom_annual_manager_rating', 'read_only', 1);
        }
        if (frm.fields_dict.custom_annual_manager_feedback) {
            set_property(frm, 'custom_annual_manager_feedback', 'read_only', 1);
        }
        if (frm.fields_dict.custom_rating_instructions) set_property(frm, 'custom_rating_instructions', 'hidden', 1);
    } else { 
        if (frm.fields_dict.custom_self_assessment_on_annual_progress) {
            set_property(frm, 'custom_self_assessment_on_annual_progress', 'read_only', 1);
        }
        if (frm.fields_dict.custom_annual_employee_performance_development_needs) {
            set_property(frm, 'custom_annual_employee_performance_development_needs', 'read_only', 0); 
        }
        if (frm.fields_dict.custom_upward_feedback_to_manager) {
            set_property(frm, 'custom_upward_feedback_to_manager', 'read_only', 1);
        }
        if (frm.fields_dict.custom_midterm_employee_upward_feedback) {
            set_property(frm, 'custom_midterm_employee_upward_feedback', 'read_only', 1);
        }
        if (frm.fields_dict.reflections) {
            set_property(frm, 'reflections', 'read_only', 0);
        }
        if (cycle.is_mid_term && frm.fields_dict.custom_midterm_manager_feedback) {
            let can_mgr_edit = (state === 'Pending Manager Review');
            set_property(frm, 'custom_midterm_manager_feedback', 'read_only', can_mgr_edit ? 0 : 1);
        }
        if (cycle.is_annual) {
            if (frm.fields_dict.custom_annual_manager_feedback) set_property(frm, 'custom_annual_manager_feedback', 'read_only', 0);
            if (frm.fields_dict.custom_annual_manager_rating) set_property(frm, 'custom_annual_manager_rating', 'read_only', 0);
            if (state === 'Pending Manager Review') {
                if (frm.fields_dict.custom_annual_manager_rating) set_property(frm, 'custom_annual_manager_rating', 'reqd', 1);
            }
        }
        let show_instructions = (cycle.is_annual && (state === 'Pending Manager Review' || state === 'Completed'));
        if (frm.fields_dict.custom_rating_instructions) set_property(frm, 'custom_rating_instructions', 'hidden', show_instructions ? 0 : 1);
    }
}

function check_cycle_dates_and_lock(frm) {
    frappe.db.get_value('Appraisal Cycle', frm.doc.appraisal_cycle, ['status', 'end_date'])
    .then(r => {
        if (r && r.message) {
            if (r.message.status !== 'In Progress') {
                frappe.msgprint({ title: __('Cycle Not Started'), indicator: 'red', message: __('Please start the Appraisal Cycle first.') });
                frm.set_value('appraisal_cycle', ''); 
            } else {
                toggle_mid_term_vs_annual(frm);
                apply_manager_security_lock(frm);

                if (frm.fields_dict.custom_objectives__achievements) {
                    let grid = frm.fields_dict.custom_objectives__achievements.grid;
                    let cycle = get_cycle_type(frm);
                    let is_employee = (frappe.session.user === frm.doc.custom_employee_email || frappe.session.user === frm.doc.employee_email);
                    let state = frm.doc.workflow_state || 'Pending';

                    safe_grid_update(grid, 'midterm_achievements', 'read_only', 1);
                    safe_grid_update(grid, 'annual_achievements', 'read_only', 1);

                    if (is_employee) {
                        if (cycle.is_mid_term) {
                            let can_edit_midterm = (state === 'Objectives Approved');
                            safe_grid_update(grid, 'midterm_achievements', 'read_only', can_edit_midterm ? 0 : 1);
                        } else if (cycle.is_annual) {
                            safe_grid_update(grid, 'annual_achievements', 'read_only', 0);
                        }
                    }
                    frm.refresh_field('custom_objectives__achievements');
                }
            }
        }
    });
}

function toggle_mid_term_vs_annual(frm) {
    let cycle = get_cycle_type(frm);
    let is_employee = (frappe.session.user === frm.doc.custom_employee_email || frappe.session.user === frm.doc.employee_email);
    let state = frm.doc.workflow_state || 'Pending';
    let grid = frm.fields_dict.custom_objectives__achievements ? frm.fields_dict.custom_objectives__achievements.grid : null;

    if (cycle.is_mid_term) {
        if (frm.fields_dict.custom_self_assessment_on_annual_progress) {
            set_property(frm, 'custom_self_assessment_on_annual_progress', 'hidden', 1); 
        }
        if (frm.fields_dict.custom_annual_employee_performance_development_needs) {
            set_property(frm, 'custom_annual_employee_performance_development_needs', 'hidden', 1);
        }
        let is_objective_phase = (state === 'Pending' || state === 'Draft' || state === 'Objective Review Pending');
        let has_feedback = frm.doc.custom_midterm_manager_feedback ? true : false;
        let show_midterm_mgr_section = is_employee ? has_feedback : !is_objective_phase;

        if (frm.fields_dict.custom_midterm_manager_feedback) {
            set_property(frm, 'custom_midterm_manager_feedback', 'hidden', show_midterm_mgr_section ? 0 : 1);
            set_property(frm, 'custom_midterm_manager_feedback', 'label', '<b>Mid-Term Manager Feedback</b>');
            let can_mgr_edit = (!is_employee && state === 'Pending Manager Review');
            set_property(frm, 'custom_midterm_manager_feedback', 'read_only', can_mgr_edit ? 0 : 1);
        }

        if (frm.fields_dict.custom_upward_feedback_to_manager) {
            set_property(frm, 'custom_upward_feedback_to_manager', 'hidden', 1);
        }

        if (frm.fields_dict.custom_midterm_employee_upward_feedback) {
            set_property(frm, 'custom_midterm_employee_upward_feedback', 'hidden', is_objective_phase ? 1 : 0);
            set_property(frm, 'custom_midterm_employee_upward_feedback', 'label', 'Employee Upward Feedback');
            set_property(frm, 'custom_midterm_employee_upward_feedback', 'read_only', is_employee ? 0 : 1);
            move_field(frm, 'custom_midterm_employee_upward_feedback', 'custom_objectives__achievements', 'after');
        }

        if (frm.fields_dict.custom_manager_review__feedback) {
            set_property(frm, 'custom_manager_review__feedback', 'hidden', 1);
        }

        let nuke_fields = [
            'custom_technical__behavio', 
            'custom_annual_manager_feedback', 
            'custom_annual_manager_rating'
        ];
        nuke_fields.forEach(f => {
            if (frm.fields_dict[f]) set_property(frm, f, 'hidden', 1);
        });
        
        if (frm.fields_dict.custom_technical__behavio) {
            set_property(frm, 'custom_technical__behavio', 'hidden', 1);
            let tech_tab = $('a.nav-link[data-fieldname="custom_technical__behavio"]').parent();
            if(tech_tab.css('display') !== 'none') tech_tab.hide();
        }

        const manager_tab = $('a.nav-link:contains("Manager Feedback")').parent();
        if (show_midterm_mgr_section) {
            if(manager_tab.css('display') === 'none') manager_tab.show();
        } else {
            if(manager_tab.css('display') !== 'none') {
                manager_tab.hide();
                if ($('a.nav-link:contains("Manager Feedback")').hasClass('active')) {
                    $('a.nav-link:contains("Self Appraisal")')[0].click();
                }
            }
        }

        if (grid) {
            let can_edit_midterm = (is_employee && state === 'Objectives Approved');
            grid.update_docfield_property('midterm_achievements', 'read_only', can_edit_midterm ? 0 : 1);
            grid.update_docfield_property('annual_achievements', 'read_only', 1);
            frm.refresh_field('custom_objectives__achievements');
        }
    } 
    else if (cycle.is_annual) {
        let has_mgr_feedback = frm.doc.custom_annual_manager_feedback ? true : false;
        let has_mgr_rating = frm.doc.custom_annual_manager_rating ? true : false;
        let show_manager_section = false;

        if (is_employee) {
            show_manager_section = (state === 'Completed' || has_mgr_feedback || has_mgr_rating);
        } else {
            show_manager_section = (state === 'Pending Manager Review' || state === 'Completed');
        }
        
        if (frm.fields_dict.custom_annual_manager_rating) {
            set_property(frm, 'custom_annual_manager_rating', 'hidden', show_manager_section ? 0 : 1);
        }
        if (frm.fields_dict.custom_annual_manager_feedback) {
            set_property(frm, 'custom_annual_manager_feedback', 'hidden', show_manager_section ? 0 : 1);
        }
        if (frm.fields_dict.custom_manager_review__feedback) {
            set_property(frm, 'custom_manager_review__feedback', 'hidden', 1);
        }
        
        if (frm.fields_dict.custom_self_assessment_on_annual_progress) {
            set_property(frm, 'custom_self_assessment_on_annual_progress', 'hidden', 0);
        }
        if (frm.fields_dict.custom_upward_feedback_to_manager) {
            set_property(frm, 'custom_upward_feedback_to_manager', 'hidden', 0);
        }
        if (frm.fields_dict.custom_annual_employee_performance_development_needs) {
            set_property(frm, 'custom_annual_employee_performance_development_needs', 'hidden', 0);
        }
        if (frm.fields_dict.custom_midterm_employee_upward_feedback) {
            set_property(frm, 'custom_midterm_employee_upward_feedback', 'hidden', 0);
        }
        if (frm.fields_dict.custom_midterm_manager_feedback) {
            set_property(frm, 'custom_midterm_manager_feedback', 'hidden', 0);
        }
        if (frm.fields_dict.reflections) {
            set_property(frm, 'reflections', 'hidden', 0);
        }
        
        if (frm.fields_dict.custom_technical__behavio) {
            set_property(frm, 'custom_technical__behavio', 'hidden', show_manager_section ? 0 : 1);
            const technical_tab = $('a.nav-link[data-fieldname="custom_technical__behavio"]').parent();
            if (show_manager_section) {
                if(technical_tab.css('display') === 'none') technical_tab.show();
            } else {
                if(technical_tab.css('display') !== 'none') technical_tab.hide();
            }
        }

        const manager_tab = $('a.nav-link:contains("Manager Feedback")').parent();
        if (show_manager_section) {
            if(manager_tab.css('display') === 'none') manager_tab.show();
        } else {
            if(manager_tab.css('display') !== 'none') {
                manager_tab.hide();
                if ($('a.nav-link:contains("Manager Feedback")').hasClass('active')) {
                    $('a.nav-link:contains("Self Appraisal")')[0].click();
                }
            }
        }

        if (grid) {
            grid.update_docfield_property('midterm_achievements', 'read_only', 1);
            if (is_employee) grid.update_docfield_property('annual_achievements', 'read_only', 0);
            frm.refresh_field('custom_objectives__achievements');
        }
    }

    if (typeof set_competency_grid_permissions === 'function') {
        set_competency_grid_permissions(frm);
    }
}

function fetch_and_render_mid_term(frm) {
    if (!frm.doc.employee) return;
    let midterm_name = frm.doc.custom_linked_midterm_appraisal;
    
    if (!midterm_name) {
        frappe.call({
            method: 'frappe.client.get_list',
            args: { 
                doctype: 'Appraisal', 
                filters: { 
                    employee: frm.doc.employee, 
                    docstatus: ['<', 2],
                    name: ['!=', frm.doc.name] 
                }, 
                fields: ['name', 'appraisal_cycle', 'creation'], 
                order_by: 'creation desc' 
            },
            callback: function(r) {
                if (r.message && r.message.length > 0) {
                    let mid_term = r.message.find(d => d.appraisal_cycle && (d.appraisal_cycle.toLowerCase().includes('mid') || d.appraisal_cycle.toLowerCase().includes('half')));
                    if (!mid_term && r.message.length > 0) mid_term = r.message[0];
                    if (mid_term) {
                        frm.set_value('custom_linked_midterm_appraisal', mid_term.name);
                        load_midterm_doc(frm, mid_term.name);
                    }
                }
            }
        });
    } else {
        load_midterm_doc(frm, midterm_name);
    }
}

function load_midterm_doc(frm, midterm_name) {
    frappe.call({
        method: 'frappe.client.get',
        args: { doctype: 'Appraisal', name: midterm_name },
        callback: function(r) {
            if (r.message) {
                let mid_term_doc = r.message;
                map_mid_term_data(frm, mid_term_doc);
                auto_copy_objectives(frm, mid_term_doc);
                auto_copy_competencies(frm, mid_term_doc); 

                setTimeout(() => {
                    const annual_fields = [
                        'custom_midterm_employee_upward_feedback',
                        'custom_midterm_manager_feedback',
                        'custom_self_assessment_on_annual_progress',
                        'custom_upward_feedback_to_manager',
                        'custom_annual_employee_performance_development_needs'
                    ];
                    annual_fields.forEach(field => {
                        if (frm.fields_dict[field]) frm.refresh_field(field);
                    });
                    enforce_field_visibility(frm);
                }, 200);
            }
        }
    });
}

function auto_copy_objectives(frm, mid_term_doc) {
    if (mid_term_doc.custom_objectives__achievements && mid_term_doc.custom_objectives__achievements.length > 0) {
        let is_empty = !frm.doc.custom_objectives__achievements || frm.doc.custom_objectives__achievements.length === 0;
        let has_one_blank = frm.doc.custom_objectives__achievements && frm.doc.custom_objectives__achievements.length === 1 && !frm.doc.custom_objectives__achievements[0].objective;

        if (is_empty || has_one_blank) {
            frm.clear_table('custom_objectives__achievements');
            $.each(mid_term_doc.custom_objectives__achievements, function(i, old_row) {
                let new_row = frm.add_child('custom_objectives__achievements');
                new_row.objective = old_row.objective || '';
                new_row.how_will_you_achieve = old_row.how_will_you_achieve || ''; 
                new_row.plan_to_achieve = old_row.plan_to_achieve || '';
                new_row.midterm_achievements = old_row.midterm_achievements || '';
                new_row.annual_achievements = '';
            });
            frm.refresh_field('custom_objectives__achievements');
        }
    }
}

function auto_copy_competencies(frm, mid_term_doc) {
    let tables = ['custom_behavioural_competencies', 'custom_executive_technical_competencies', 'custom_leadership_technical_competencies'];
    let dirty = false;
    tables.forEach(table => {
        if (mid_term_doc[table] && mid_term_doc[table].length > 0 && (!frm.doc[table] || frm.doc[table].length === 0)) {
            mid_term_doc[table].forEach(old_row => {
                let new_row = frm.add_child(table);
                new_row.competency_name = old_row.competency_name;
                new_row.rating = ''; 
            });
            dirty = true;
        }
    });
    if (dirty) {
        if (frm.fields_dict.custom_behavioural_competencies) frm.refresh_field('custom_behavioural_competencies');
        if (frm.fields_dict.custom_executive_technical_competencies) frm.refresh_field('custom_executive_technical_competencies');
        if (frm.fields_dict.custom_leadership_technical_competencies) frm.refresh_field('custom_leadership_technical_competencies');
    }
}

function map_mid_term_data(frm, mid_term_doc) {
    if (mid_term_doc) {
        let emp_fb = mid_term_doc.custom_midterm_employee_upward_feedback || mid_term_doc.custom_upward_feedback_to_manager || '';
        if (emp_fb && frm.fields_dict.custom_midterm_employee_upward_feedback) {
            frm.set_value('custom_midterm_employee_upward_feedback', emp_fb);
        }
        let mgr_fb = mid_term_doc.custom_midterm_manager_feedback || mid_term_doc.custom_manager_review__feedback || '';
        if (mgr_fb && frm.fields_dict.custom_midterm_manager_feedback) {
            frm.set_value('custom_midterm_manager_feedback', mgr_fb);
        }
    }
}

function set_competency_grid_permissions(frm) {
    let cycle = get_cycle_type(frm);
    let can_edit = (frm.doc.workflow_state === 'Pending Manager Review');
    let tables = ['custom_behavioural_competencies', 'custom_executive_technical_competencies', 'custom_leadership_technical_competencies'];

    tables.forEach(table => {
        if (frm.fields_dict[table]) {
            let grid = frm.fields_dict[table].grid;
            safe_grid_update(grid, 'competency_name', 'read_only', 1);
            safe_grid_update(grid, 'rating', 'read_only', 1);
            safe_grid_update(grid, 'annual_rating', 'read_only', 1);

            if (can_edit) {
                if (cycle.is_mid_term) safe_grid_update(grid, 'rating', 'read_only', 0);
                else if (cycle.is_annual) safe_grid_update(grid, 'annual_rating', 'read_only', 0);
            }
            frm.set_df_property(table, 'cannot_add_rows', true);
            frm.set_df_property(table, 'cannot_delete_rows', true);
        }
    });
}

function setup_competencies(frm) {
    if (!frm.doc.employee) return;
    let cycle = get_cycle_type(frm);

    if (cycle.is_mid_term) {
        let nuke_fields = [
            'custom_technical__behavio', 
            'custom_annual_manager_feedback', 
            'custom_manager_review__feedback',
            'custom_rating_instructions',
            'custom_annual_employee_performance_development_needs',
            'custom_midterm_employee_upward_feedback'
        ];
        nuke_fields.forEach(f => {
            if (frm.fields_dict[f]) set_property(frm, f, 'hidden', 1);
        });
        if (frm.fields_dict.custom_technical__behavio) {
            set_property(frm, 'custom_technical__behavio', 'hidden', 1);
            $('a.nav-link[data-fieldname="custom_technical__behavio"]').parent().hide();
        }
        if (frm.fields_dict.custom_behavioural_competencies) set_property(frm, 'custom_behavioural_competencies', 'hidden', 1);
        if (frm.fields_dict.custom_executive_technical_competencies) set_property(frm, 'custom_executive_technical_competencies', 'hidden', 1);
        if (frm.fields_dict.custom_leadership_technical_competencies) set_property(frm, 'custom_leadership_technical_competencies', 'hidden', 1);
        return;
    }

    let is_employee = (frappe.session.user === frm.doc.custom_employee_email || frappe.session.user === frm.doc.employee_email);
    let state = frm.doc.workflow_state;
    let show_competencies = !is_employee && (state === 'Pending Manager Review' || state === 'Completed');

    if (frm.fields_dict.custom_technical__behavio) {
        set_property(frm, 'custom_technical__behavio', 'hidden', show_competencies ? 0 : 1);
    }

    if (!show_competencies) {
        if (frm.fields_dict.custom_behavioural_competencies) set_property(frm, 'custom_behavioural_competencies', 'hidden', 1);
        if (frm.fields_dict.custom_executive_technical_competencies) set_property(frm, 'custom_executive_technical_competencies', 'hidden', 1);
        if (frm.fields_dict.custom_leadership_technical_competencies) set_property(frm, 'custom_leadership_technical_competencies', 'hidden', 1);
        return; 
    }

    frappe.db.get_value('Employee', frm.doc.employee, 'grade').then(r => {
        let grade = r.message ? (r.message.grade || '') : '';
        let is_exec = grade.startsWith('E');
        let is_lead = grade.startsWith('L') || grade.startsWith('M');

        if (frm.fields_dict.custom_behavioural_competencies) set_property(frm, 'custom_behavioural_competencies', 'hidden', 0);
        if (frm.fields_dict.custom_executive_technical_competencies) set_property(frm, 'custom_executive_technical_competencies', 'hidden', is_exec ? 0 : 1);
        if (frm.fields_dict.custom_leadership_technical_competencies) set_property(frm, 'custom_leadership_technical_competencies', 'hidden', is_lead ? 0 : 1);

        let can_edit = (state === 'Pending Manager Review');
        if (can_edit) auto_populate_competencies(frm, is_exec, is_lead);

        setTimeout(() => {
            set_competency_grid_permissions(frm);
            apply_custom_hover_tooltips(frm); 
        }, 100);
    });
}

function auto_populate_competencies(frm, is_exec, is_lead) {
    let behav_list = ['Communication', 'Persuasion and Influencing', 'Working with People', 'Innovation', 'Strategic Thinking', 'Driving Results', 'Developing People', 'Analytical Ability', 'Planning And Organizing', 'Managing Change'];
    let exec_list = ['Task Execution', 'Support to Team and Coordination', 'Problem Solving', 'Supervision and Oversight', 'Information Management', 'Support Planning and Adaptability', 'Learning Orientation'];
    let lead_list = ['Program Design & Implementation', 'Health Systems Strengthening', 'Research & Data Management', 'Community Engagement and Mobilization', 'Partnerships & Stakeholder Management', 'Resource Mobilisation and Financial Management', 'Governance & Leadership', 'Advocacy & Policy Influence', 'Digital and Innovation Capacity'];

    let dirty = false;
    if (!frm.doc.custom_behavioural_competencies || frm.doc.custom_behavioural_competencies.length === 0) {
        behav_list.forEach(c => { let row = frm.add_child('custom_behavioural_competencies'); row.competency_name = c; });
        dirty = true;
    }
    if (is_exec && (!frm.doc.custom_executive_technical_competencies || frm.doc.custom_executive_technical_competencies.length === 0)) {
        exec_list.forEach(c => { let row = frm.add_child('custom_executive_technical_competencies'); row.competency_name = c; });
        dirty = true;
    }
    if (is_lead && (!frm.doc.custom_leadership_technical_competencies || frm.doc.custom_leadership_technical_competencies.length === 0)) {
        lead_list.forEach(c => { let row = frm.add_child('custom_leadership_technical_competencies'); row.competency_name = c; });
        dirty = true;
    }
    if (dirty) {
        if (frm.fields_dict.custom_behavioural_competencies) frm.refresh_field('custom_behavioural_competencies');
        if (frm.fields_dict.custom_executive_technical_competencies) frm.refresh_field('custom_executive_technical_competencies');
        if (frm.fields_dict.custom_leadership_technical_competencies) frm.refresh_field('custom_leadership_technical_competencies');
    }
}

function apply_custom_hover_tooltips(frm) {
    if (!frm.fields_dict.custom_leadership_technical_competencies && 
        !frm.fields_dict.custom_executive_technical_competencies && 
        !frm.fields_dict.custom_behavioural_competencies) return;

    if (frm.custom_hover_tooltips_bound) return; 
    frm.custom_hover_tooltips_bound = true;

    if ($('#custom-rating-floating-box').length === 0) {
        $('body').append(`
            <div id="custom-rating-floating-box" style="
                display: none;
                position: fixed;
                z-index: 9999;
                background: #ffffff;
                border: 1px solid #d1d8dd;
                box-shadow: 0px 8px 24px rgba(0, 0, 0, 0.15);
                border-radius: 8px;
                padding: 16px;
                width: 380px;
                font-family: inherit;
                font-size: 13px;
                line-height: 1.5;
                color: #1a1a1a;
                pointer-events: none;
            "></div>
        `);
    }

    let raw_dict = {
        'Communication': `<div style="margin-bottom: 10px;"><b><span style="color: #1c9b4f;">PROFICIENT:</span></b> Communicates effectively.<br>• Speaks and writes clearly, concisely and articulately.</div>`,
        'Persuasion and Influencing': `<div style="margin-bottom: 10px;"><b><span style="color: #1c9b4f;">PROFICIENT:</span></b> Prepares thoroughly.</div>`,
        'Working with People': `<div style="margin-bottom: 10px;"><b><span style="color: #1c9b4f;">PROFICIENT:</span></b> Builds trust.</div>`,
        'Innovation': `<div style="margin-bottom: 10px;"><b><span style="color: #1c9b4f;">PROFICIENT:</span></b> Challenges the status quo.</div>`,
        'Strategic Thinking': `<div style="margin-bottom: 10px;"><b><span style="color: #1c9b4f;">PROFICIENT:</span></b> Aligns ongoing work actions with strategic objectives.</div>`,
        'Driving Results': `<div style="margin-bottom: 10px;"><b><span style="color: #1c9b4f;">PROFICIENT:</span></b> Takes delivery ownership for self.</div>`,
        'Developing People': `<div style="margin-bottom: 10px;"><b><span style="color: #1c9b4f;">PROFICIENT:</span></b> Takes accountability for own development.</div>`,
        'Analytical Ability': `<div style="margin-bottom: 10px;"><b><span style="color: #1c9b4f;">PROFICIENT:</span></b> Ensures delivery of accurate data analytics.</div>`,
        'Planning And Organizing': `<div style="margin-bottom: 10px;"><b><span style="color: #1c9b4f;">PROFICIENT:</span></b> Takes accountability for own work efficiency.</div>`,
        'Managing Change': `<div style="margin-bottom: 10px;"><b><span style="color: #1c9b4f;">PROFICIENT:</span></b> Responding and adjusting to change.</div>`
    };

    let tooltips = {};
    for (let key in raw_dict) {
        let clean_key = key.toLowerCase().replace(/[^a-z0-9]/g, '');
        tooltips[clean_key] = raw_dict[key];
    }

    $(document).on('mousemove', 'div[data-fieldname="competency_name"]', function(e) {
        let cell = $(this);
        let text = cell.text().trim() || cell.find('input').val() || '';
        let clean_text = text.toLowerCase().replace(/[^a-z0-9]/g, '');

        if (clean_text && tooltips[clean_text]) {
            cell.removeAttr('title');
            cell.css({ 'cursor': 'help' });

            let floating_box = $('#custom-rating-floating-box');
            floating_box.html(tooltips[clean_text]);

            let x = e.clientX + 15; 
            let y = e.clientY + 15; 

            if (x + 380 > window.innerWidth) x = e.clientX - 395; 
            if (y + floating_box.outerHeight() > window.innerHeight) y = e.clientY - floating_box.outerHeight() - 15; 

            floating_box.css({ top: y + 'px', left: x + 'px', display: 'block' });
        }
    });

    $(document).on('mouseleave', 'div[data-fieldname="competency_name"]', function() {
        $('#custom-rating-floating-box').css('display', 'none');
    });
}

// --- FORCE CORRECT HEADER BADGE ---
function force_correct_header_badge(frm) {
    let state = frm.doc.workflow_state || 'Pending';
    let color = 'orange';
    
    if (state === 'Completed') {
        color = 'green';
    } else if (state.includes('Review')) {
        color = 'blue';
    } else if (state.includes('Approved')) {
        color = 'green';
    } else if (state.includes('Rejected')) {
        color = 'red';
    }

    setTimeout(() => {
        if (frm.page && frm.page.set_indicator) {
            frm.page.set_indicator(state, color);
        }
    }, 200);
}

frappe.ui.form.on('Appraisal', {
    refresh: function(frm) {
        // VIP Roles for HR Documents
        const allowed_roles = [
            "HR Manager", 
            "System Manager", 
            "Administrator"
        ];

        const has_access = frappe.user_roles.some(role => allowed_roles.includes(role));

        if (!has_access) {
            frm.page.wrapper.find('.form-footer').hide(); 
            frm.page.wrapper.find('.timeline').hide();
            frm.page.wrapper.find('.new-timeline').hide();
            frm.page.wrapper.find('.form-dashboard').hide(); 
        } else {
            frm.page.wrapper.find('.form-footer').show();
            frm.page.wrapper.find('.timeline').show();
            frm.page.wrapper.find('.new-timeline').show();
        }
    }
});

